import React, { useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import './Meeting.css';

import { useLocation } from 'react-router-dom';

function Meeting({ stream, handleMuteUnmute, handleOpenCloseCamera }) {
  const location = useLocation();
  const { isMicEnabled, isCamEnabled } = location.state;
  const userVideo = useRef();
  const navigate = useNavigate();

  useEffect(() => {
    if (stream) {
      // Use the passed stream instead of requesting a new one
      userVideo.current.srcObject = stream;
    }
  }, [stream]);

  const handleLeave = () => {
    navigate('/');
  };

  return (
    <Router>
      <Routes>
        <Route path="/" element={
          <div className="App">
            <main>
              <VideoDisplay videoRef={userVideo} id="userVideo" muted={true} />
              <ControlPanel
                onHost={handleHostMeeting}
                onJoin={handleJoinMeeting}
                onMuteUnmute={handleMuteUnmute}
                onToggleCamera={() => handleOpenCloseCamera(userVideo)}
              />
            </main>
          </div>
        } />
        {/* Other routes... */}
      </Routes>
    </Router>
  );
}

export default MainComponent;
